import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const out='review-evidence/no-brow-editable-bundle',origin='http://127.0.0.1:8140';
const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});const p=await browser.newPage({viewport:{width:1600,height:715}}),errors=[];p.on('pageerror',e=>errors.push(e.message));
await p.goto(origin+'/review-evidence/selected-gesture-review/');await p.waitForFunction(()=>window.selectedReview?.ready);const live=await p.locator('#after svg').evaluate(n=>n.outerHTML);
await p.setContent('<!doctype html><style>html,body{margin:0;background:#24493b}svg{display:block;width:1600px;height:715px}svg text{font:32px system-ui,sans-serif;fill:#f1f7ee;text-anchor:middle}</style>'+live);await p.evaluate(()=>Promise.all([...document.querySelectorAll('image')].map(n=>new Promise((resolve,reject)=>{const i=new Image();i.onload=resolve;i.onerror=reject;i.src=n.getAttribute('href')}))));const baseline=await p.screenshot();
await p.goto(origin+'/'+out+'/preview.html');await p.evaluate(()=>Promise.all([...document.querySelectorAll('image')].map(n=>new Promise((resolve,reject)=>{const i=new Image();i.onload=resolve;i.onerror=reject;i.src=n.getAttribute('href')}))));const preview=await p.screenshot({path:out+'/Ranca-Cana-no-brows.png'});assert.ok(baseline.equals(preview),'standalone SVG/HTML export must render pixel-identically to the no-brow scene');
await p.setViewportSize({width:1000,height:447});await p.screenshot({path:out+'/Ranca-Cana-normal-size.png'});
const count=await p.evaluate(()=>Object.fromEntries([...document.querySelectorAll('[data-character]')].map(c=>[c.dataset.character,{rasterImages:c.querySelectorAll('image').length,editablePaths:c.querySelectorAll('path').length,separateBrows:[...c.querySelector('[data-preserved-face]').children].filter(n=>n.tagName.toLowerCase()==='path'&&n!==c.querySelector('[data-preserved-face]').lastElementChild).length}])));
for(const key of ['ranca','cana']){assert.equal(count[key].rasterImages,1);assert.equal(count[key].separateBrows,0);assert.ok((await fs.readFile(out+'/assets/'+key+'-body.webp')).equals(await fs.readFile('assets/mascots/poses/'+key+'-body.webp')));}
assert.deepEqual(errors,[]);
const closeups=await p.evaluate(()=>{
  const original=document.querySelector('svg');
  const card=(title,sub,viewBox)=>{const svg=original.cloneNode(true);svg.setAttribute('viewBox',viewBox);return '<article><h1>'+title+'</h1><p>'+sub+'</p>'+svg.outerHTML+'<footer><strong>← Connected edge: outside</strong><strong>Open gap: inside →</strong><span>Inside points toward this character’s body center.</span></footer></article>';};
  return '<!doctype html><html lang="en"><meta charset="utf-8"><title>Eye and waving-hand details</title><style>*{box-sizing:border-box}html,body{margin:0;background:#173e31;color:#f1f7ee;font-family:system-ui,sans-serif}main{width:1440px;padding:32px;display:grid;grid-template-columns:1fr 1fr;gap:28px}article{background:#24493b;border:1px solid #617b6b;border-radius:16px;overflow:hidden}h1{font-size:30px;margin:24px 24px 8px}p{font-size:21px;margin:0 24px 18px}svg{width:100%;height:415px;display:block}footer{padding:22px 24px;display:grid;grid-template-columns:1fr 1fr;gap:16px;font-size:18px}footer span{grid-column:1 / -1;color:#d0ddd4;font-size:17px}</style><main>'+card('Ranca · longer eye lines','Eye width +25%; no lashes or eyebrows.','200 245 340 235')+card('Cana · paired outward sweeps','Each eye sweeps outward; a slight asymmetry keeps her sass.','945 295 365 200')+'</main></html>';
});
await fs.writeFile(out+'/eye-hand-closeups.html',closeups);
await p.setViewportSize({width:1440,height:700});await p.setContent(closeups);await p.evaluate(()=>Promise.all([...document.querySelectorAll('image')].map(n=>new Promise((resolve,reject)=>{const i=new Image();i.onload=resolve;i.onerror=reject;i.src=n.getAttribute('href')}))));await p.locator('main').screenshot({path:out+'/eye-hand-closeups.png'});
const canaCloseup=await p.evaluate(()=>{const article=document.querySelectorAll('article')[1].cloneNode(true);article.querySelector('svg').setAttribute('viewBox','1030 295 285 160');article.querySelector('footer').remove();return '<!doctype html><html lang="en"><meta charset="utf-8"><title>Cana upper-lid lash detail</title><style>html,body{margin:0;background:#24493b;color:#f1f7ee;font:22px system-ui,sans-serif}main{width:960px}h1{font-size:32px;margin:0;padding:24px 28px 8px}p{margin:0;padding:0 28px 20px}svg{display:block;width:960px;height:auto}</style><main>'+article.outerHTML+'</main></html>';});
await fs.writeFile(out+'/Cana-lashes-closeup.html',canaCloseup);await p.setViewportSize({width:960,height:750});await p.setContent(canaCloseup);await p.evaluate(()=>Promise.all([...document.querySelectorAll('image')].map(n=>new Promise((resolve,reject)=>{const i=new Image();i.onload=resolve;i.onerror=reject;i.src=n.getAttribute('href')}))));await p.locator('main').screenshot({path:out+'/Cana-lashes-closeup.png'});
await browser.close();await fs.writeFile(out+'/export-check.json',JSON.stringify({standalonePixelIdentical:true,sourceScene:'12db327 with Cana eye/lash orientation corrected into an outward-facing pair',layers:count,bodyImageBytesUnchanged:true,jsxValidation:'Generated as literal named SVG paths; not locally compiled. MagicPath worker must validate the imported component.',pageErrors:errors},null,2));console.log(JSON.stringify(count));
